 function submitCashierScan(lines:StockReceiptLine[],plate?:string,posId?:string,reference?:string,notes?:string,proof?:{name:string;data:string}):boolean{
  if(!user||locked||bodGate||!((cashierScanMode==='receive'&&(user.role==='cashier'||user.role==='admin'))||(cashierScanMode==='consume'&&user.role==='cashier')))return false;
  try{
   if(cashierScanMode==='receive'){
    const next=submitStockReceipt(db,lines,reference||'',notes||'',user.id,proof,true);commitInventory(next);notify('Stock In submitted as pending. A DIFFERENT Admin must recount the physical goods before stock increases.');setCashierScanMode(null);return true;
   }
   if(!posId)throw new Error('Choose an existing open POS Draft before requesting stock.');
   const next=requestStockIssue(db,posId,lines,notes||'',user.id);
   const target=db.pos.find(p=>p.id===posId)!;
   commitInventory(next);
   setCashierScanMode(null);setFixedScanPOS('');setView('pos');setPosTab('drafts');setSearch('');setStatusFilter('All');
   setRecordId(target.id);setDialog('posRecord');
   notify(`Pending release for ${target.no}. No stock was deducted. Wait for independent Admin authorization BEFORE releasing physical items.`);
   return true;
  }catch(err){notify((err as Error).message);return false;}
 }
