   commitInventory(next);setInventoryReview(null);notify(inventoryReview.kind==='receipt'?(approved?'Independently counted receipt posted. Stock increased.':'Receipt rejected; stock unchanged.'):(approved?'Release authorized. Stock deducted with POS audit link.':'Release rejected; stock unchanged.'));return true;
