    {user.role==='cashier'&&<div className="inventory-admin-actions" style={{padding:'12px 16px',display:'flex',gap:8,flexWrap:'wrap'}}><button type="button" className="button button-primary" onClick={()=>{setCashierScanMode('receive');setStockPrefillProductId('');setFixedScanPOS('')}}><Plus size={16}/> Add Stock · Single / Bulk Scan</button><button type="button" className="button button-secondary" onClick={()=>{setCashierScanMode('consume');setFixedScanPOS('')}}><ScanBarcode size={16}/> Request Stock Release · Single / Bulk Scan</button></div>}
