    {(user.role==='cashier'||user.role==='admin'&&cashierScanMode==='receive')&&cashierScanMode&&<StockScanPanel key={`${cashierScanMode}-${stockPrefillProductId}-${user.role==='admin'?(selectedBranch==='ALL'?user.branch:selectedBranch):user.branch}`} db={db} branch={user.role==='admin'?(selectedBranch==='ALL'?user.branch:selectedBranch):user.branch} mode={cashierScanMode} preselectedProductId={stockPrefillProductId||undefined} adminReceive={false} onSubmit={submitCashierScan} onClose={()=>{setCashierScanMode(null);setStockPrefillProductId('')}}/>}
