     {reportTab==='parts'&&user.role!=='cashier'&&<><div className="panel-head"><div><h3>Monthly Parts Expenses</h3><span>{partsPeriod==='month'?`Selected month: ${partsMonth}`:`Custom range: ${partsFrom||'Start'} – ${partsTo||'Latest'}`} · RFP Parts Only</span></div><div className="panel-buttons"><button className="button button-primary" onClick={()=>{if(selectedBranch==='ALL'){notify('Select one branch to print this report.');return;}printRFPParts(db,selectedBranch,partsFrom,partsTo)}}><Printer size={15}/> Preview / Print Parts Report</button></div></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Date</th><th>Part</th><th>Supplier</th><th>Plate Number</th><th>Car</th><th>Branch</th><th className="num">Qty</th><th className="num">Unit Cost</th><th className="num">Total Amount</th><th>Linked POS</th><th>Receipt</th><th>Status</th></tr></thead><tbody>{selectedParts.slice((reportPage-1)*30,reportPage*30).map(e=>{const vehicle=db.pos.find(p=>p.id===e.linkedPosId)?.vehicle||db.pos.find(p=>p.branch===e.branch&&normalizePlate(p.plate)===normalizePlate(e.plate||''))?.vehicle||e.car||'Not recorded';return <tr key={e.id}><td>{datePH(e.date)}</td><td>{e.description}</td><td>{e.payee}</td><td>{e.plate||'—'}</td><td>{vehicle}</td><td>{BRANCH_NAME(e.branch)}</td><td className="num">{e.quantity||1}</td><td className="num">{pesos(e.unitCost||0)}</td><td className="num">{pesos(e.amount)}</td><td>{db.pos.find(p=>p.id===e.linkedPosId)?.no||'Unlinked'}</td><td>{e.proof?.name||'Missing'}</td><td><StatusPill status={e.status}/></td></tr>})}</tbody></table>{selectedParts.length===0&&<Empty title="No parts purchases in this period"/>}</div><div className="pagination"><button className="button button-secondary" disabled={reportPage===1} onClick={()=>setReportPage(n=>n-1)}>Previous</button><span>Page {reportPage} · {selectedParts.length} records · 30 per page</span><button className="button button-secondary" disabled={reportPage*30>=selectedParts.length} onClick={()=>setReportPage(n=>n+1)}>Next</button></div></>}
